<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#222}h2{margin:0 0 6px}.meta{margin-bottom:16px;color:#666}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:6px;text-align:left}th{background:#f2f2f2}.num{text-align:right}</style></head><body><h2>{{ config('restaurant.name') }} — Sales Report</h2><div class="meta">Generated {{ now()->format('d M Y H:i') }}</div><table><thead><tr><th>Order</th><th>Customer</th><th>Type</th><th class="num">Subtotal</th><th class="num">Discount</th><th class="num">Tax</th><th class="num">Total</th><th class="num">Paid</th><th class="num">Balance</th><th>Status</th><th>Date</th></tr></thead><tbody>@foreach($orders as $o)<tr><td>{{ $o->order_number }}</td><td>{{ $o->customer?->name ?? 'Walk-in' }}</td><td>{{ $o->order_type }}</td><td class="num">{{ number_format((float)$o->subtotal) }}</td><td class="num">{{ number_format((float)$o->discount) }}</td><td class="num">{{ number_format((float)$o->tax) }}</td><td class="num">{{ number_format((float)$o->total) }}</td><td class="num">{{ number_format((float)$o->paid_amount) }}</td><td class="num">{{ number_format((float)$o->balance) }}</td><td>{{ $o->status }}</td><td>{{ $o->ordered_at?->format('d/m/Y H:i') }}</td></tr>@endforeach</tbody></table></body></html>
